@page "/apply"
@rendermode InteractiveServer
@using sv_9b7ad2a6db7a4ce999663520d9e33c47.Models
@using sv_9b7ad2a6db7a4ce999663520d9e33c47.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    @if (!_submitted)
    {
        <!-- Step Indicator Bar -->
        <div class="step-indicator">
            @for (int i = 0; i < _stepNames.Length; i++)
            {
                var stepIndex = i;
                var stepClass = GetStepClass(stepIndex);
                <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                    <div class="step-circle">
                        @if (stepIndex < _currentStep)
                        {
                            <span>&#10003;</span>
                        }
                        else
                        {
                            <span>@(stepIndex + 1)</span>
                        }
                    </div>
                    <div class="step-label">@_stepNames[stepIndex]</div>
                </div>
                @if (stepIndex < _stepNames.Length - 1)
                {
                    <div class="step-connector @(stepIndex < _currentStep ? "completed" : "")"></div>
                }
            }
        </div>

        <!-- Validation Errors -->
        @if (_errors.Count > 0)
        {
            <div class="validation-errors">
                @foreach (var error in _errors)
                {
                    <p>@error</p>
                }
            </div>
        }

        <!-- Step 1: Personal Info -->
        @if (_currentStep == 0)
        {
            <div class="form-step">
                <h2>Personal Information</h2>
                <div class="form-group">
                    <label for="fullName">Full Name *</label>
                    <input id="fullName" type="text" @bind="_fullName" placeholder="Enter your full name" />
                </div>
                <div class="form-group">
                    <label for="email">Email *</label>
                    <input id="email" type="email" @bind="_email" placeholder="Enter your email" />
                </div>
                <div class="form-group">
                    <label for="phone">Phone *</label>
                    <input id="phone" type="tel" @bind="_phone" placeholder="Enter your phone number" />
                </div>
                <div class="form-group">
                    <label for="address">Address *</label>
                    <input id="address" type="text" @bind="_address" placeholder="Enter your address" />
                </div>
                <div class="form-actions">
                    <button class="btn btn-primary" @onclick="NextStep" disabled="@_isValidating">
                        @if (_isValidating)
                        {
                            <span>Validating...</span>
                        }
                        else
                        {
                            <span>Next</span>
                        }
                    </button>
                </div>
            </div>
        }

        <!-- Step 2: Work History -->
        @if (_currentStep == 1)
        {
            <div class="form-step">
                <h2>Work History</h2>
                @for (int i = 0; i < _workEntries.Count; i++)
                {
                    var index = i;
                    <div class="work-entry-card">
                        <div class="work-entry-header">
                            <h3>Position @(index + 1)</h3>
                            @if (_workEntries.Count > 1)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                        </div>
                        <div class="form-group">
                            <label>Company Name *</label>
                            <input type="text" @bind="_workEntries[index].Company" placeholder="Company name" />
                        </div>
                        <div class="form-group">
                            <label>Job Title *</label>
                            <input type="text" @bind="_workEntries[index].Title" placeholder="Job title" />
                        </div>
                        <div class="form-row">
                            <div class="form-group">
                                <label>Start Date *</label>
                                <input type="date" @bind="_workEntries[index].StartDate" />
                            </div>
                            <div class="form-group">
                                <label>End Date</label>
                                <input type="date" @bind="_workEntries[index].EndDate" disabled="@_workEntries[index].IsCurrent" />
                            </div>
                        </div>
                        <div class="form-group form-check">
                            <input type="checkbox" id="current-@index" @bind="_workEntries[index].IsCurrent" />
                            <label for="current-@index">I currently work here</label>
                        </div>
                        <div class="form-group">
                            <label>Description *</label>
                            <textarea @bind="_workEntries[index].Description" placeholder="Describe your responsibilities and achievements" rows="3"></textarea>
                        </div>
                    </div>
                }
                <button class="btn btn-secondary" @onclick="AddWorkEntry">+ Add Another Position</button>
                <div class="form-actions">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextStep">Next</button>
                </div>
            </div>
        }

        <!-- Step 3: References -->
        @if (_currentStep == 2)
        {
            <div class="form-step">
                <h2>References</h2>
                @for (int i = 0; i < _references.Count; i++)
                {
                    var index = i;
                    <div class="reference-card">
                        <div class="work-entry-header">
                            <h3>Reference @(index + 1)</h3>
                            @if (_references.Count > 2)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                            }
                        </div>
                        <div class="form-group">
                            <label>Name *</label>
                            <input type="text" @bind="_references[index].Name" placeholder="Reference name" />
                        </div>
                        <div class="form-group">
                            <label>Relationship *</label>
                            <input type="text" @bind="_references[index].Relationship" placeholder="e.g., Former Manager" />
                        </div>
                        <div class="form-group">
                            <label>Email *</label>
                            <input type="email" @bind="_references[index].Email" placeholder="Reference email" />
                        </div>
                        <div class="form-group">
                            <label>Phone *</label>
                            <input type="tel" @bind="_references[index].Phone" placeholder="Reference phone" />
                        </div>
                    </div>
                }
                @if (_references.Count < 3)
                {
                    <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
                }
                <div class="form-actions">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextStep">Next</button>
                </div>
            </div>
        }

        <!-- Step 4: Cover Letter -->
        @if (_currentStep == 3)
        {
            <div class="form-step">
                <h2>Cover Letter</h2>
                <div class="form-group">
                    <label for="coverLetter">Write your cover letter *</label>
                    <textarea id="coverLetter" @bind="_coverLetter" @bind:event="oninput" placeholder="Tell us why you're a great fit for this role..." rows="12"></textarea>
                    <div class="char-count @(_coverLetter.Length > 2000 ? "over-limit" : "")">
                        @_coverLetter.Length / 2000 characters
                    </div>
                </div>
                <div class="form-actions">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextStep">Next</button>
                </div>
            </div>
        }

        <!-- Step 5: Review & Submit -->
        @if (_currentStep == 4)
        {
            <div class="form-step">
                <h2>Review &amp; Submit</h2>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Personal Information</h3>
                        <button class="btn btn-link" @onclick="() => GoToStep(0)">Edit</button>
                    </div>
                    <dl class="review-data">
                        <dt>Full Name</dt><dd>@_fullName</dd>
                        <dt>Email</dt><dd>@_email</dd>
                        <dt>Phone</dt><dd>@_phone</dd>
                        <dt>Address</dt><dd>@_address</dd>
                    </dl>
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Work History</h3>
                        <button class="btn btn-link" @onclick="() => GoToStep(1)">Edit</button>
                    </div>
                    @foreach (var entry in _workEntries)
                    {
                        <div class="review-entry">
                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                            <p>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</p>
                            <p>@entry.Description</p>
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>References</h3>
                        <button class="btn btn-link" @onclick="() => GoToStep(2)">Edit</button>
                    </div>
                    @foreach (var reference in _references)
                    {
                        <div class="review-entry">
                            <strong>@reference.Name</strong> (@reference.Relationship)
                            <p>@reference.Email &bull; @reference.Phone</p>
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Cover Letter</h3>
                        <button class="btn btn-link" @onclick="() => GoToStep(3)">Edit</button>
                    </div>
                    <p class="cover-letter-preview">@_coverLetter</p>
                </div>

                <div class="form-actions">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                        @if (_isSubmitting)
                        {
                            <span>Submitting...</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                </div>
            </div>
        }
    }
    else
    {
        <!-- Submission Confirmation -->
        <div class="confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h2>Application Submitted!</h2>
            <p>Your application has been successfully submitted.</p>
            <p class="application-id">Application ID: <strong>@_applicationId</strong></p>
            <p>We'll review your application and get back to you soon.</p>
        </div>
    }
</div>

@code {
    private readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
    private int _currentStep;
    private List<string> _errors = new();
    private bool _isValidating;
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;

    // Step 1: Personal Info
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2: Work History
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string _coverLetter = string.Empty;

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == _currentStep) return "active";
        if (stepIndex < _currentStep) return "completed";
        return "future";
    }

    private void NavigateToStep(int stepIndex)
    {
        if (stepIndex < _currentStep)
        {
            _currentStep = stepIndex;
            _errors.Clear();
        }
    }

    private void GoToStep(int stepIndex)
    {
        _currentStep = stepIndex;
        _errors.Clear();
    }

    private async Task NextStep()
    {
        _errors.Clear();

        if (!ValidateCurrentStep())
            return;

        if (_currentStep == 0)
        {
            _isValidating = true;
            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            _isValidating = false;

            if (!emailValid)
            {
                _errors.Add("The email address could not be validated. Please use a valid email.");
                return;
            }
        }

        _currentStep++;
    }

    private void PreviousStep()
    {
        _errors.Clear();
        if (_currentStep > 0)
            _currentStep--;
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(_fullName)) _errors.Add("Full name is required.");
                if (string.IsNullOrWhiteSpace(_email)) _errors.Add("Email is required.");
                if (string.IsNullOrWhiteSpace(_phone)) _errors.Add("Phone is required.");
                if (string.IsNullOrWhiteSpace(_address)) _errors.Add("Address is required.");
                break;
            case 1:
                for (int i = 0; i < _workEntries.Count; i++)
                {
                    var entry = _workEntries[i];
                    if (string.IsNullOrWhiteSpace(entry.Company)) _errors.Add($"Position {i + 1}: Company name is required.");
                    if (string.IsNullOrWhiteSpace(entry.Title)) _errors.Add($"Position {i + 1}: Job title is required.");
                    if (entry.StartDate == default) _errors.Add($"Position {i + 1}: Start date is required.");
                    if (string.IsNullOrWhiteSpace(entry.Description)) _errors.Add($"Position {i + 1}: Description is required.");
                }
                break;
            case 2:
                for (int i = 0; i < _references.Count; i++)
                {
                    var r = _references[i];
                    if (string.IsNullOrWhiteSpace(r.Name)) _errors.Add($"Reference {i + 1}: Name is required.");
                    if (string.IsNullOrWhiteSpace(r.Relationship)) _errors.Add($"Reference {i + 1}: Relationship is required.");
                    if (string.IsNullOrWhiteSpace(r.Email)) _errors.Add($"Reference {i + 1}: Email is required.");
                    if (string.IsNullOrWhiteSpace(r.Phone)) _errors.Add($"Reference {i + 1}: Phone is required.");
                }
                break;
            case 3:
                if (string.IsNullOrWhiteSpace(_coverLetter)) _errors.Add("Cover letter is required.");
                if (_coverLetter.Length > 2000) _errors.Add("Cover letter must be 2000 characters or fewer.");
                break;
        }
        return _errors.Count == 0;
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;

        var personal = new PersonalInfo(_fullName, _email, _phone, _address);
        var workEntries = _workEntries.Select(e => new WorkEntry(
            e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
        )).ToList();
        var work = new WorkHistory(workEntries);
        var references = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

        var application = new JobApplication(personal, work, references, _coverLetter);
        _applicationId = await ApplicationService.SubmitApplicationAsync(application);

        _isSubmitting = false;
        _submitted = true;
    }

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
            _workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private class WorkEntryModel
