            <p class="application-id">Application ID: <strong>@_applicationId</strong></p>
            <p>We'll review your application and get back to you soon.</p>
        </div>
    }
</div>

@code {
    private readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
    private int _currentStep;
    private List<string> _errors = new();
    private bool _isValidating;
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;

    // Step 1: Personal Info
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2: Work History
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string _coverLetter = string.Empty;

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == _currentStep) return "active";
        if (stepIndex < _currentStep) return "completed";
        return "future";
    }

    private void NavigateToStep(int stepIndex)
    {
        if (stepIndex < _currentStep)
        {
            _currentStep = stepIndex;
            _errors.Clear();
        }
    }

    private void GoToStep(int stepIndex)
    {
        _currentStep = stepIndex;
        _errors.Clear();
    }

    private async Task NextStep()
    {
        _errors.Clear();

        if (!ValidateCurrentStep())
            return;

        if (_currentStep == 0)
        {
            _isValidating = true;
            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            _isValidating = false;

            if (!emailValid)
            {
                _errors.Add("The email address could not be validated. Please use a valid email.");
                return;
            }
        }

        _currentStep++;
    }

    private void PreviousStep()
    {
        _errors.Clear();
        if (_currentStep > 0)
            _currentStep--;
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(_fullName)) _errors.Add("Full name is required.");
                if (string.IsNullOrWhiteSpace(_email)) _errors.Add("Email is required.");
                if (string.IsNullOrWhiteSpace(_phone)) _errors.Add("Phone is required.");
                if (string.IsNullOrWhiteSpace(_address)) _errors.Add("Address is required.");
                break;
            case 1:
                for (int i = 0; i < _workEntries.Count; i++)
                {
                    var entry = _workEntries[i];
                    if (string.IsNullOrWhiteSpace(entry.Company)) _errors.Add($"Position {i + 1}: Company name is required.");
                    if (string.IsNullOrWhiteSpace(entry.Title)) _errors.Add($"Position {i + 1}: Job title is required.");
                    if (entry.StartDate == default) _errors.Add($"Position {i + 1}: Start date is required.");
                    if (string.IsNullOrWhiteSpace(entry.Description)) _errors.Add($"Position {i + 1}: Description is required.");
                }
                break;
            case 2:
                for (int i = 0; i < _references.Count; i++)
                {
                    var r = _references[i];
                    if (string.IsNullOrWhiteSpace(r.Name)) _errors.Add($"Reference {i + 1}: Name is required.");
                    if (string.IsNullOrWhiteSpace(r.Relationship)) _errors.Add($"Reference {i + 1}: Relationship is required.");
                    if (string.IsNullOrWhiteSpace(r.Email)) _errors.Add($"Reference {i + 1}: Email is required.");
                    if (string.IsNullOrWhiteSpace(r.Phone)) _errors.Add($"Reference {i + 1}: Phone is required.");
                }
                break;
            case 3:
                if (string.IsNullOrWhiteSpace(_coverLetter)) _errors.Add("Cover letter is required.");
                if (_coverLetter.Length > 2000) _errors.Add("Cover letter must be 2000 characters or fewer.");
                break;
        }
        return _errors.Count == 0;
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;

        var personal = new PersonalInfo(_fullName, _email, _phone, _address);
        var workEntries = _workEntries.Select(e => new WorkEntry(
            e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
        )).ToList();
        var work = new WorkHistory(workEntries);
        var references = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

        var application = new JobApplication(personal, work, references, _coverLetter);
        _applicationId = await ApplicationService.SubmitApplicationAsync(application);

        _isSubmitting = false;
        _submitted = true;
    }

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
            _workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

