.review-data dd {
    margin: 0;
    color: #333;
    font-size: 0.9rem;
}

.review-entry {
    padding: 0.75rem 0;
    border-bottom: 1px solid #eee;
}

.review-entry:last-child {
    border-bottom: none;
    padding-bottom: 0;
}

.review-entry p {
    margin: 0.25rem 0 0;
    color: #666;
    font-size: 0.85rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    color: #333;
    font-size: 0.9rem;
    line-height: 1.5;
}

/* Validation Errors */
.validation-errors {
    background: #fdecea;
    border: 1px solid #f5c6cb;
    border-radius: 8px;
    padding: 1rem;
    margin-bottom: 1.5rem;
}

.validation-errors p {
    margin: 0.25rem 0;
    color: #c0392b;
    font-size: 0.85rem;
